    """
    This function is used to get the table of contents (TOC) items.
    :param md: Markdown instance. The instance of the Markdown class.
    :param tokens: List. The list of the tokens.
    :param state: Dictionary. The dictionary of the state.
    :return: No return values.
    """
    toc_items = []
    for i, t in enumerate(tokens):
        if t.type == 'heading_open':
            level = int(tokens[i + 1].tag[1])
            if min_level <= level <= max_level:
