                        (level, t.map[0] + 1, tokens[i + 1].content, heading_id(t.map[0] + 1, tokens[i + 1].content))
                    )
                else:
                    toc_items.append(
                        (level, t.map[0] + 1, tokens[i + 1].content, tokens[i + 1].map[0] + 1)
                    )
    state['toc_items'] = toc_items

