def _walk_parse(root, parser_state):
    """
    This function walks the parse tree to find headings and saves them to the state.env.
    :param root: ElementTree.Element. The root element of the parse tree.
    :param parser_state: dict. The state of the parser.
    :return: No return values.
    """
    if root.tag in ['h{}'.format(i) for i in range(min_level, max_level + 1)]:
        text = ''.join(root.itertext())
        if heading_id:
            id = heading_id(text)
        else:
            id = text.lower().strip()
            id = id.replace(' ', '-')
            id = id.replace('?', '')
            id = id.replace(':', '')
            id = id.replace('(', '')
            id = id.replace(')', '')
        item = {
            'level': int(root.tag[1]),
            'id': id,
            'name': text,
            'children': []
        }
        if not parser_state['toc_depth'] or item['level'] <= parser_state['toc_depth']:
            parser_state['toc_depth'] = item['level']
        if not parser_state['toc_last'] or item['level'] == parser_state['toc_last']['level']:
            parser_state['toc_last']['children'].append(item)
        else:
            while parser_state['toc_last'] and item['level'] <= parser_state['toc_last']['level']:
                parser_state['toc_last'] = parser_state['toc_last']['parent']
            parser_state['toc_last']['children'].append(item)
        parser_state['toc_last'] = item
    else:
        for child in root:
            _walk_parse(child, parser_state)

