def toc_treeprocessor(tree, _):
    # tree: list of Elements
    # [<h1>Some text</h1>, <h2>Some text</h2>, ...]
    toc_tokens = []
    for element in tree:
        if element.tag in ['h%d' % n for n in range(min_level, max_level + 1)]:
            text = striptags(element.text)
            anchor = toc_anchor(text, element.tag[1:])
            element.text = anchor + text
            if element.tag == 'h1':
                toc_tokens.append({'level': 1, 'id': element.get('id'), 'text': text, 'children': []})
            else:
                toc_tokens[-1]['children'].append({'level': element.tag[1], 'id': element.get('id'), 'text': text})
    state.toc_tokens = toc_tokens

