def _walk_parse(root, toc_levels):

    """
    This function walks the tree of the parsed markdown document and save the TOC items into the state.env.
    :param root: ElementTree.Element. The root of the parsed markdown document.
    :param toc_levels: List. The list of the TOC items.
    :return: No return values.
    """

    if root is None:
        return

    if root.tag == 'h1':
        toc_levels.append({
            'level': 1,
            'id': heading_id(root.text),
            'name': root.text,
            'children': []
        })
        return

    if root.tag[0] == 'h' and min_level <= int(root.tag[1]) <= max_level:
        toc_levels[-1]['children'].append({
            'level': int(root.tag[1]),
            'id': heading_id(root.text),
            'name': root.text,
            'children': []
        })
        return

    for child in root:
        _walk_parse(child, toc_levels[-1]['children'])

