    for j in range(len(line)):
        # if it's a backspace,
        if line[j] == "\b":
            # pop the last character off the stack if it exists
            if stack:
                stack.pop()

        # if it's a linefeed,
        elif line[j] == "\r":
            # if there are any characters on the stack, empty the stack
            if stack:
                stack = []

            # if it's a normal character,
        else:
            # push it onto the stack
            stack.append(line[j])

    # join the characters in the stack to make a string
    lines[i] = "".join(stack)

# join all the lines together with a linefeed
return "\n".join(lines)

