def _validate_callable(val):
    if val is None:
        return None

    if inspect.isfunction(val) or inspect.ismethod(val):
        if arity == -1 or arity == val.__code__.co_argcount:
            return val

    elif inspect.isclass(val):
        val = val()
        if inspect.isfunction(val) or inspect.ismethod(val):
            if arity == -1 or arity == val.__code__.co_argcount:
                return val

    val = validate_string(val)

    if not val:
        raise TypeError("Value must be a callable object")

    module_name, _, class_name = val.rpartition(".")

    if module_name:
        module = importlib.import_module(module_name)
        val = getattr(module, class_name)
        if inspect.isfunction(val) or inspect.ismethod(val):
            if arity == -1 or arity == val.__code__.co_argcount:
                return val
        elif inspect.isclass(val):
            val = val()
            if inspect.isfunction(val) or inspect.ismethod(val):
                if arity == -1 or arity == val.__code__.co_argcount:
                    return val

    raise TypeError("Value must be a callable object")

