    if inspect.isfunction(val) or inspect.ismethod(val):
        if arity == -1 or arity == val.__code__.co_argcount:
            return val
        else:
            raise TypeError("Arity of the passed value is not correct. Expected: %s, got: %s" % (arity, val.__code__.co_argcount))

    if inspect.isclass(val):
        raise TypeError("Passed value is a class. Please pass a function or a method.")

    if not callable(val):
        raise TypeError("Passed value is not callable.")

    if not hasattr(val, '__module__') or not hasattr(val, '__qualname__'):
        raise TypeError("Passed object is not a valid function/method.")

    obj = None
    try:
        obj = getattr(sys.modules[val.__module__], val.__qualname__)
    except Exception:
        raise TypeError("Unable to import the passed object.")

    if not inspect.isfunction(obj) and not inspect.ismethod(obj):
        raise TypeError("Passed value is not a function or a method.")

    if arity == -1 or arity == obj.__code__.co_argcount:
        return obj
    else:
        raise TypeError("Arity of the passed value is not correct. Expected: %s, got: %s" % (arity, obj.__code__.co_argcount))

return _validate_callable

def _validate_callable(val):
    if isinstance(val, str):
        try:
            mod_name, obj_name = val.split(':')
        except ValueError as err:
            raise TypeError("Error parsing callable string: '%s'" % val) from err
        obj = getattr(importlib.import_module(mod_name), obj_name)
    else:
        obj = val

    if not six.callable(obj):
        raise TypeError("Value is not callable: %s" % val)
    if not hasattr(obj, '__code__'):
        fname = getattr(obj, '__name__', getattr(obj, '__class__').__name__)
        raise TypeError("%s() has no __code__ attribute" % fname)
    if arity != -1 and arity != obj.__code__.co_argcount:
        fname = getattr(obj, '__name__', getattr(obj, '__class__').__name__)
        raise TypeError("Arity of %s() is %d, expected %d" % (fname, obj.__code__.co_argcount, arity))
    return obj

return _validate_callable

