    if filename.endswith(".gz"):
        stream = pa.input_stream(pa.input_stream("gz://" + filename).read())
    return pa.ipc.open_stream(stream).read_all()
except pa.lib.ArrowInvalid as e:
    if "arrow.ArrowInvalid: Not a file-like object" in str(e):
        # The file-like object was not readable.
        # This can happen if pyarrow does not support the compression method used.
        # We then try to read the file using the python package.
        # This is slower, but works for all formats.
        return pa.ipc.open_stream(filename).read_all()
    else:
        # Some other error happened
        raise e

