from random import randint
from random import choice as rchoice
from string import ascii_lowercase as lcase
from string import ascii_uppercase as ucase

def gen_word(word_length: int) -> str:
    """Generate a random word of a certain length."""
    return "".join(rchoice(lcase + ucase) for _ in range(word_length))

def gen_sentence(word_range: tuple[int, int]) -> str:
    """Generate a random sentence with a random number of words."""
    word_length = randint(word_range[0], word_range[1])
    word = gen_word(word_length)
    if word_length in range(3, 9):
        word += ","
    if word_length in range(10, 21):
        word += "."
    return word[0].upper() + word[1:]

def gen_paragraph(sentence_range: tuple[int, int]) -> str:
    """Generate a random paragraph with a random number of sentences."""
    sentence_length = randint(sentence_range[0], sentence_range[1])
    return " ".join(
        gen_sentence(sentence_length) for _ in range(sentence_length)
    ).capitalize() + "."

if html:
    return "\n".join(gen_paragraph((min, max)) for _ in range(n))

return "\n\n".join(gen_paragraph((min, max)) for _ in range(n))

