    if not dry_run:
        self.client.run_sql_file(self.schema_file)
    return

# If the current version is the same as the desired version, do nothing.
if current_version == self.schema_version:
    logger.info("Schema %s is already up-to-date", self.name)
    return

# Otherwise, migrate the schema.
logger.info("Migrating schema %s", self.name)

# Make sure the current version is valid.
if current_version > self.schema_version:
    logger.error("Schema %s is ahead of the schema version", self.name)
    return

# Run each migration in order.
for migration in self.get_migration_files():
    if migration["version"] > current_version:
        if not dry_run:
            self.client.run_sql_file(migration["file"])

# Get the current version.
current_version = self.get_installed_version()
if current_version is None:
    logger.info(f"Creating schema {self.name} from {self.schema_file}")
    if not dry_run:
        self.client.execute(self.schema_file)
elif current_version == self.schema_version:
    logger.info(f"Schema {self.name} is already up-to-date")
else:
    logger.info(f"Migrating schema {self.name} from {current_version} to {self.schema_version}")
    if not dry_run:
        self.migrate_schema(current_version)

