def get_children(revision: Revision) -> Iterator[Revision]:
    for rev_id in revision._all_nextrev:
        yield map_[rev_id]

def get_children_map(revisions: Collection[Revision]) -> Dict[Revision, Set[Revision]]:
    children_map: Dict[Revision, Set[Revision]] = collections.defaultdict(set)
    for revision in revisions:
        for child in get_children(revision):
            children_map[revision].add(child)
    return children_map

def get_parent_map(revisions: Collection[Revision]) -> Dict[Revision, Set[Revision]]:
    parent_map: Dict[Revision, Set[Revision]] = collections.defaultdict(set)
    for revision in revisions:
        for parent in get_parents(revision):
            parent_map[parent].add(revision)
    return parent_map

def get_parents(revision: Revision) -> Iterator[Revision]:
    for rev_id in revision._all_down_revisions:
        yield map_[rev_id]

def get_roots(revisions: Collection[Revision]) -> Set[Revision]:
    children_map = get_children_map(revisions)
    return set(revisions).difference(
        set(itertools.chain(*children_map.values()))
    )

def get_leaves(revisions: Collection[Revision]) -> Set[Revision]:
    parent_map = get_parent_map(revisions)
    return set(revisions).difference(
        set(itertools.chain(*parent_map.values()))
    )

