# A helper function to get all the revisions that are not dependencies of any revision.
def get_leaf_revisions(revisions: Collection[Revision]) -> Set[str]:
    dependencies = set()
    for revision in revisions:
        dependencies.update(get_dependencies(revision))
    return set(revision.revision for revision in revisions).difference(
        dependencies
    )

# A helper function to get all the revisions that are not dependents of any revision.
def get_root_revisions(revisions: Collection[Revision]) -> Set[str]:
    dependents = set()
    for revision in revisions:
        dependents.update(get_dependents(revision))
    return set(revision.revision for revision in revisions).difference(
        dependents
    )

# A helper function to get the revisions that are not dependencies of any revision and are not dependents of any revision.
def get_independent_revisions(
    revisions: Collection[Revision],
) -> Set[str]:
    return get_leaf_revisions(revisions).intersection(
        get_root_revisions(revisions)
    )

