    if data.extension.ext_name != data.entry_point.name:
        logger.error(
            f"Extension name ({data.extension.ext_name}) does not match entry point name ({data.entry_point.name})."
        )
        return False
    # Check that the extension dependencies are installed.
    for dep in data.entry_point.dist.requires():
        if pkg_resources.working_set.find(pkg_resources.Requirement.parse(dep)) is None:
            logger.error(f"Extension dependency {dep} is not installed.")
            return False
    # Check that the extension environment is valid.
    try:
        data.extension.validate_environment()
    except Exception as e:
        logger.error(f"Extension environment is invalid: {e}")
        return False
    # Check that the extension has a valid config schema and default config.
    try:
        config_schema = data.extension.get_config_schema()
        if config_schema is None:
            logger.error("Extension config schema is invalid: None")
            return False
        config_defaults = data.extension.get_default_config()
        if config_defaults is None:
            logger.error("Extension config defaults is invalid: None")
            return False
        config_schema.deserialize(config_defaults)
    except Exception as e:
        logger.error(f"Extension config is invalid: {e}")
        return False
except Exception as e:
    logger.error(f"Extension is invalid: {e}")
    return False
