    if name.startswith("XDG_"):
        dirs[name] = pathlib.Path(value).expanduser()

dirs_file = dirs.get("XDG_CONFIG_DIRS", "~/.config/user-dirs.dirs")
dirs_file = pathlib.Path(dirs_file).expanduser()

if dirs_file.exists():
    with open(dirs_file, "rt") as f:
        for line in f:
            if line.startswith("XDG_"):
                name, value = line.split("=")
                name = name.strip()
                value = value.strip("\"'")
                value = pathlib.Path(value).expanduser()
                dirs[name] = value

return dirs

# Create a dictionary to hold the XDG Base Directories.
dirs = {}

# Get the environment variables related to XDG Base Directories.
for var in ("XDG_CACHE_DIR", "XDG_CONFIG_DIR", "XDG_DATA_DIR", "XDG_MUSIC_DIR", "XDG_PICTURES_DIR", "XDG_TEMPLATES_DIR", "XDG_VIDEOS_DIR"):
    # If the environment variable is set, add it to the dictionary.
    if var in os.environ:
        dirs[var] = pathlib.Path(os.path.expanduser(os.environ[var]))

# If the `user-dirs.dirs` file exists, parse it and add the directories to the dictionary.
if pathlib.Path("/etc/xdg/user-dirs.dirs").is_file():
    # Parse the file and get the values of the XDG Base Directory variables.
    config = configparser.ConfigParser()
    config.read("/etc/xdg/user-dirs.dirs")
    for var in ("XDG_CACHE_DIR", "XDG_CONFIG_DIR", "XDG_DATA_DIR", "XDG_MUSIC_DIR", "XDG_PICTURES_DIR", "XDG_TEMPLATES_DIR", "XDG_VIDEOS_DIR"):
        # If the variable is defined, add it to the dictionary.
        if var in config["XDG_USER_DIRS"]:
            dirs[var] = pathlib.Path(config["XDG_USER_DIRS"][var])

return dirs

dirs = {}
for name in os.environ:
    if name.startswith("XDG_"):
        dirs[name] = pathlib.Path(os.environ[name]).expanduser()
user_dirs_file = pathlib.Path("~/.config/user-dirs.dirs").expanduser()
if user_dirs_file.exists():
    with open(user_dirs_file) as f:
        for line in f:
            line = line.strip()
            if line.startswith("#") or not "=" in line:
                continue
            key, value = line.split("=")
            if key.startswith("XDG_"):
                dirs[key] = pathlib.Path(value.strip('"'))
return dirs

dirs = {}

# Get the values of the environment variables.
for var in ["XDG_CACHE_DIR", "XDG_CONFIG_DIR", "XDG_DATA_DIR", "XDG_RUNTIME_DIR"]:
    dirs[var] = pathlib.Path(os.environ.get(var)).expanduser()

# If the user-dirs.dirs file exists, parse it and update the dictionary.
user_dirs_file = pathlib.Path(os.environ.get("HOME")).expanduser() / ".config" / "user-dirs.dirs"
if user_dirs_file.exists():
    with open(user_dirs_file, "r") as f:
        for line in f.readlines():
            if line.startswith("#"):
                continue
            key, value = line.strip().split("=")
            dirs[key] = pathlib.Path(value).expanduser()

return dirs

