sources = []
sinks = []
for key, value in data.items():
    if key == 'sources':
        for source_key, source_value in value.items():
            sources.append(Source(source_key))
    elif key == 'sinks':
        for sink_key, sink_value in value.items():
            sinks.append(Sink.from_json(sink_key, sink_value))
    else:
        raise ValueError("Invalid key in trigger_word_file")

