    # If the variable name is in the condition_keys dictionary, substitute the variable with its value.
    else:
        return _matches_after_expansion(string_to_check, string_to_check_against.replace(string_to_check_against.split('${')[1].split('}')[0], condition_keys[string_to_check_against.split('${')[1].split('}')[0]]), condition_keys)

# If the second string contains a regular expression, check if the first string matches the second string.
if '::' in string_to_check_against:
    pattern = string_to_check_against.split('::')[1]
    return re.match(pattern, string_to_check) is not None

# If the second string does not contain a wildcard, variable, or regular expression, check if the first string is the same as the second string.
return string_to_check == string_to_check_against

if '${' in string_to_check_against:
    # if there is a variable in the string, replace it with the corresponding value in condition_keys
    if condition_keys is None:
        condition_keys = CaseInsensitiveDict({})
    if string_to_check_against.startswith('${') and string_to_check_against.endswith('}'):
        # if the string is a variable, replace it with the corresponding value in condition_keys
        variable_name = string_to_check_against[2:-1]
        if variable_name in condition_keys:
            string_to_check_against = condition_keys[variable_name]
        else:
            return False
    else:
        # if the string contains a variable, replace it with the corresponding value in condition_keys
        string_to_check_against = re.sub(r'(\$\{.*?\})', lambda m: str(condition_keys.get(m.group(1)[2:-1], m.group(1))), string_to_check_against)

