    # if the string to check against contains wildcards, use regex to check if the string to check matches the string to check against
    return _compose_pattern(string_to_check_against).match(string_to_check) is not None
else:
    # if the string to check against doesn't contain wildcards, use normal string matching
    return string_to_check_against == string_to_check

