while True:
    # Run each source.
    for name, source in self.sources.items():
        logger.debug(f"Running source '{name}'")
        try:
            artifacts = source.run()
        except Exception:
            logger.exception(f"Error running source '{name}'")
            continue

        # Track artifacts across sources.
        if not isinstance(artifacts, collections.Iterable):
            logger.error(f"Source '{name}' returned non-iterable")
            continue

        for artifact in artifacts:
            # Skip artifacts that are whitelisted.
            if self._is_whitelisted(artifact):
                continue

            # Track artifact state.
            if self.statedb.contains(str(artifact)):
                logger.debug(
                    f"Reject {str(artifact)} from further processing because it is already in the state database."
                )
                continue
            self.statedb.add(str(artifact))

            # Send artifact to each operator.
            for operator in self.operators.values():
                try:
                    operator.run(artifact)
                except Exception:
                    logger.exception(f"Error running operator '{name}'")
                    continue

    # Run once if not configured to run as a daemon.
    if not self.config.daemon():
        break

    # Sleep for configured interval.
    logger.debug(f"Sleeping for {self.config.interval()} seconds")
    time.sleep(self.config.interval())

