        module = importlib.import_module(
            "musicdl.source.{}".format(source)
        )
        source = module.MusicSource()
        songs = source.search(keyword)
        songs = sorted(songs, key=lambda song: song.rate, reverse=True)
        self.logger.info(
            "Searched {} for {} songs".format(source.source, len(songs))
